Here's the improved solution for the Lumen application that extracts a specified frame from a video using the `ffmpeg` command-line tool. The application is structured according to the OpenAPI schema provided.

<FILEPATH>
bootstrap/app.php
</FILEPATH>
<CODE>
<?php

require_once __DIR__.'/../vendor/autoload.php';

$app = new Laravel\Lumen\Application(
    dirname(__DIR__)
);

$app->withFacades();
$app->withEloquent();

$app->router->group(['namespace' => 'App\Http\Controllers'], function ($router) {
    require __DIR__.'/../routes/web.php';
});

return $app;
</CODE>

<FILEPATH>
routes/web.php
</FILEPATH>
<CODE>
<?php

/** @var \Laravel\Lumen\Routing\Router $router */

$router->post('/extract', 'FrameExtractController@extract');
</CODE>

<FILEPATH>
app/Http/Controllers/FrameExtractController.php
</FILEPATH>
<CODE>
<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

class FrameExtractController extends Controller
{
    public function extract(Request $request)
    {
        $this->validate($request, [
            'video' => 'required|file|mimes:mp4,avi,mov|max:10240', // Limit file size to 10MB
            'frameNumber' => 'required|integer|min:0',
        ]);

        $video = $request->file('video');
        $frameNumber = $request->input('frameNumber');
        $videoPath = $video->getPathname();
        $outputImagePath = sys_get_temp_dir() . '/frame_' . $frameNumber . '.png';

        $command = sprintf(
            'ffmpeg -i %s -vf "select=eq(n\,%d)" -vframes 1 %s',
            escapeshellarg($videoPath),
            $frameNumber,
            escapeshellarg($outputImagePath)
        );

        exec($command, $output, $returnVar);

        if ($returnVar !== 0 || !file_exists($outputImagePath)) {
            return response()->json(['error' => "Frame at index $frameNumber could not be found."], Response::HTTP_NOT_FOUND);
        }

        return response()->download($outputImagePath, 'frame.png', ['Content-Type' => 'image/png'])->deleteFileAfterSend(true);
    }
}
</CODE>

